import{_ as a,o as e,c as r,a3 as o}from"./chunks/framework.BM_-pWjS.js";const d="/bridge-lite/manual/assets/comp.CFWlsuNa.png",b=JSON.parse('{"title":"比較する","description":"","frontmatter":{},"headers":[],"relativePath":"ja/compare.md","filePath":"ja/compare.md"}'),l={name:"ja/compare.md"};function i(n,t,s,h,p,c){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="比較する" tabindex="-1">比較する <a class="header-anchor" href="#比較する" aria-label="Permalink to &quot;比較する&quot;">​</a></h1><p><img src="'+d+'" alt="比較ビュー"></p><p>bridge-lite は「撮って出し（JPEG）」「RAW」「現像済み」を<strong>1つのグループ</strong>として扱います。グループを構成する個々のファイル——撮って出し・RAW・現像済みのそれぞれ——を<strong>メンバー</strong>と呼びます。</p><h2 id="なぜ三種を並べるのか" tabindex="-1">なぜ三種を並べるのか <a class="header-anchor" href="#なぜ三種を並べるのか" aria-label="Permalink to &quot;なぜ三種を並べるのか&quot;">​</a></h2><p>現像によって思い通りの色が出せることもあれば、カメラ出力の方が素直に良い場合もあります。また、現像を重ねるうちに元の色調を見失うこともあります。三つを行き来することで、判断の根拠を確かめながらセレクトができます。</p><h2 id="写真の切り替え" tabindex="-1">写真の切り替え <a class="header-anchor" href="#写真の切り替え" aria-label="Permalink to &quot;写真の切り替え&quot;">​</a></h2><p>矢印キーと <code>Ctrl + Tab</code> の動作は、グループ間・メンバー間で切り替えられます。</p><table tabindex="0"><thead><tr><th>操作</th><th>デフォルト</th><th>[グループ / メンバー] 押下後</th></tr></thead><tbody><tr><td>← / → / ↑ / ↓</td><td>グループ間を移動</td><td>メンバー間を移動</td></tr><tr><td>Ctrl + Tab / Ctrl + Shift + Tab</td><td>メンバー間を移動</td><td>グループ間を移動</td></tr></tbody></table><p>画面上部の <strong>[グループ / メンバー]</strong> をクリックすると、この操作が逆になります。</p><h2 id="画像のみモード" tabindex="-1">画像のみモード <a class="header-anchor" href="#画像のみモード" aria-label="Permalink to &quot;画像のみモード&quot;">​</a></h2><p><strong>[画像のみ]</strong> をクリックすると、RAW ファイルをグループから除外し、撮って出し（JPEG）と現像済みだけを比較できます。</p><p>RAW の表示は Apple のレンダリングエンジンがその都度生成したプレビューであり、実際の現像結果とは異なります。RAW を除いて比較することで、実際に書き出される画像同士をより正確に見比べられます。</p><h2 id="ペアリングの仕組み" tabindex="-1">ペアリングの仕組み <a class="header-anchor" href="#ペアリングの仕組み" aria-label="Permalink to &quot;ペアリングの仕組み&quot;">​</a></h2><p>RAW と JPG の自動ペアリングは以下の順で行われます。</p><ol><li><strong>ステム名</strong> — <code>DSC04867.ARW</code> と <code>DSC04867.JPG</code> のようにファイル名（拡張子を除く部分）が一致するもの</li><li><strong>EXIF タイムスタンプ</strong> — ステム名が異なっても撮影時刻が一致するもの</li><li><strong>pHash</strong> — 知覚ハッシュによる視覚的類似度</li></ol><p>EXIF 情報を持たないファイルや、構図が似通った別カットは誤認識する場合があります。</p><h2 id="現像バリアントとは" tabindex="-1">現像バリアントとは <a class="header-anchor" href="#現像バリアントとは" aria-label="Permalink to &quot;現像バリアントとは&quot;">​</a></h2><p>Lightroom などで書き出した JPEG や TIFF が、同じステム名で同じフォルダに存在する場合、bridge-lite はそれを「現像済み」バリアントとして自動的に認識します。</p><p>EXIF 情報を持たないファイルや、構図が似通った別カットは誤認識する場合があります。特に、納品前に意図的に EXIF を削除している場合は pHash のみが頼りとなるため、類似した構図の別カットが誤ってグループ化される可能性があります。</p>',19)])])}const _=a(l,[["render",i]]);export{b as __pageData,_ as default};
